<?php
require '_init.php';$pageTitle='Manage Orders';$allowed=['Pending','Confirmed','Preparing','Ready','Delivered','Cancelled'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'';if(in_array($status,$allowed,true)){$s=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$s->execute([$status,$id]);set_flash('Order status updated.');}redirect('orders.php');}
$orders=$pdo->query("SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC")->fetchAll();require '../includes/header.php';
?>
<section class="page-heading"><span class="eyebrow">ADMIN</span><h1>Customer Orders</h1></section><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Delivery address</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($orders as $o):$s=$pdo->prepare("SELECT f.name,oi.quantity FROM order_items oi JOIN food_items f ON f.id=oi.food_id WHERE oi.order_id=?");$s->execute([$o['id']]); ?><tr><td>#<?= (int)$o['id'] ?><br><small><?= e($o['created_at']) ?></small></td><td><?= e($o['name']) ?><br><small><?= e($o['email']) ?></small></td><td><?php foreach($s->fetchAll() as $i): ?><?= e($i['name']) ?> × <?= (int)$i['quantity'] ?><br><?php endforeach; ?></td><td><?= money($o['total_amount']) ?></td><td><?= e($o['delivery_address']) ?></td><td><?= e($o['status']) ?></td><td><form method="post" class="status-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach($allowed as $a): ?><option <?= $o['status']===$a?'selected':'' ?>><?= e($a) ?></option><?php endforeach; ?></select><button class="small-btn">Save</button></form></td></tr><?php endforeach; ?></tbody></table></div>
<?php require '../includes/footer.php'; ?>
